function reduceOptimisticCart(payload) {
  const qty = {};
  const pending = {};
  for (const act of payload.actions || []) {
    if (act.type === 'ADD_OPTIMISTIC') {
      qty[act.sku] = (qty[act.sku] || 0) + act.delta;
      pending[act.mutation_id] = { sku: act.sku, delta: act.delta };
    } else if (act.type === 'MUTATION_CONFIRMED') {
      delete pending[act.mutation_id];
    } else if (act.type === 'MUTATION_FAILED' && pending[act.mutation_id]) {
      const p = pending[act.mutation_id];
      qty[p.sku] = Math.max(0, (qty[p.sku] || 0) - p.delta);
      delete pending[act.mutation_id];
    }
  }
  return { items: qty };
}
